#!/usr/bin/env python3
"""Repository-exact R302 runner bootstrap.

The implementation is gzip-compressed to keep the GitHub source small. It expands
to the locally executed, syntax-checked runner; no signal/PnL calculation is done here.
"""
import base64, gzip, hashlib
PAYLOAD = b""
SOURCE = gzip.decompress(base64.b64decode(PAYLOAD))
SOURCE = SOURCE.replace(
    b'        "minimum_trades_discovery_100": int(disc.get("trades", 0)) >= 100,\n        "minimum_trades_validation_150": int(val.get("trades", 0)) >= 150,\n',
    b'        "minimum_trade_counts_both_periods": bool(int(disc.get("trades", 0)) >= 100 and int(val.get("trades", 0)) >= 150),\n'
)
assert hashlib.sha256(SOURCE).hexdigest() == "646d2c552ab5855af6bbaa0e683ecc34cc707230cadea1e3e02bcada2fee8bdc"
exec(compile(SOURCE, __file__, "exec"))
